const SECTION_NAMES = {
  1: 'Knowledge of Capital Markets',
  2: 'Understanding Products and Their Risks',
  3: 'Understanding Trading, Customer Accounts and Prohibited Activities',
  4: 'Overview of Regulatory Framework',
}

const q = (
  section, number, topic, difficulty, question, questionTr, options, optionsTr,
  correctAnswer, explanation, explanationTr, ruleReference, keyTakeaway,
) => ({
  id: `q-${section}-${String(number).padStart(2, '0')}`,
  section,
  sectionName: SECTION_NAMES[section],
  topic,
  difficulty,
  question,
  questionTr,
  options,
  optionsTr,
  correctAnswer,
  explanation,
  explanationTr,
  ruleReference,
  keyTakeaway,
})

